INSERT INTO `ai_chat_message` VALUES (1678, 1781604279872581693, 1677, 1, 10, 'assistant', 'gpt-3.5-turbo', 11, '苹果是一种常见的水果，属于蔷薇科苹果属植物。苹果具有丰富的营养，含有多种维生素、矿物质和纤维，有助于保持健康。苹果有不同的品种，有红色、黄色、绿色等不同颜色的苹果。它们可以生吃、烹饪、制作果汁等多种方式食用，是人们喜爱的水果之一。', b'0', '1', '2024-05-22 07:31:44', NULL, '2024-07-05 01:30:39', b'0', 1);
