INSERT INTO `ai_chat_message` VALUES (2280, 1781604279872581731, 2279, 1, NULL, 'assistant', 'ERNIE 4.0', 10, '你好，有什么关于土豆的问题我可以为你解答吗？土豆是一种常见的食材，很多人都非常喜欢它。无论是烹饪还是种植，土豆都有很多值得探讨的话题。请告诉我你具体想了解哪方面的信息，我会尽力提供帮助。', b'1', '1', '2024-07-06 15:55:40', NULL, '2024-07-06 15:55:42', b'0', 1);
